let data=null,direction='outbound';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const taipei=d=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const age=t=>t?(Date.now()-Date.parse(t))/60000:Infinity;
const stamp=t=>t?new Date(t).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false}):'尚無資料';
$('date').value=taipei(new Date());
function render(){if(!data)return;const date=$('date').value,source=data.days?.[date],rows=source?.trains?.filter(t=>t.direction===direction)||[];const stale=age(source?.checkedAt)>15;
 $('freshness').textContent=source?`列車查詢：${stamp(source.checkedAt)}${stale?' ｜資料已過期，請至台鐵確認最新狀態。':' ｜定期擷取，非秒級即時。'}${source.error?' ｜本次更新失敗，保留先前資料。':''}`:'此日期尚未取得班次資料，請查詢台鐵官方時刻表。';
 $('trains').innerHTML=rows.length?rows.map(t=>`<article class="train"><div class="train-top"><b>${esc(t.type)} ${esc(t.no)}</b><span>${direction==='outbound'?'往瑞穗':'往花蓮方向'}</span></div><div class="times"><div><strong>${esc(t.departure)}</strong><span>${esc(t.from)} 出發</span></div><div class="track"></div><div><strong>${esc(t.arrival)}</strong><span>${esc(t.to)} 抵達</span></div></div><span class="badge ${stale?'warning':''}">${esc(stale?'狀態已過期':t.status?`即時狀態：${t.status}`:'時刻已取得・即時狀態未提供')}</span>${t.to==='花蓮'&&t.no==='431'?'<p class="note">此班不停吉安，請在花蓮下車。</p>':''}<a target="_blank" rel="noopener" href="https://www.railway.gov.tw/tra-tip-web/tip/tip001/tip112/querybytrainno?rideDate=${date.replaceAll('-','/')}&trainNo=${encodeURIComponent(t.no)}">官方車次與動態 ↗</a></article>`).join(''):'<div class="empty">尚無這一天的資料。<a href="https://www.railway.gov.tw/tra-tip-web/tip/tip001/tip112/gobytime" target="_blank" rel="noopener">查詢台鐵時刻表 ↗</a></div>';
 $('rail-status').textContent=(data.rail?.text||'尚未取得路線公告')+(age(data.rail?.checkedAt)>15?'（資料已過期）':'')+' · '+stamp(data.rail?.checkedAt);
 $('weather').innerHTML=['吉安鄉','瑞穗鄉','花蓮市'].map(name=>{const w=data.weather?.[name],old=age(w?.checkedAt)>180;const periods=w?.hours?.filter(h=>h.date===date&&Number(h.time.slice(0,2))>=(direction==='outbound'?5:16)&&Number(h.time.slice(0,2))<=(direction==='outbound'?8:19))||[];return `<article><h3>${name}</h3><span class="muted">${old?'氣象資料已過期':'氣象擷取 '+stamp(w?.checkedAt)}</span>${periods.length?periods.filter((_,i)=>i%2===0).map(h=>`<div class="period"><b>${esc(h.time)} 預報</b><p class="temp">${esc(h.temperature)}°C</p><p>${esc(h.description||'天氣狀況未提供')}<br>降雨機率 ${esc(h.rain||'未提供')}<br>風力 ${esc(h.wind||'未提供')}</p></div>`).join(''):'<p>此日期／時段尚無預報。</p>'}<a target="_blank" rel="noopener" href="${esc(w?.url||'https://www.cwa.gov.tw/V8/C/W/County/County.html?CID=10015')}">官方完整預報 ↗</a></article>`}).join('');
 $('collection-info').textContent=`最近嘗試更新：${stamp(data.attemptedAt)}。${data.errors?.length?'部分來源失敗：'+data.errors.join('；'):''}`;
}
async function refresh(){ $('refresh').disabled=true;try{const r=await fetch(`data.json?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw Error();data=await r.json();if(!$('date').dataset.chosen){const now=new Date(),hour=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',hour:'2-digit',hour12:false}).format(now));direction=hour>=20?'outbound':hour>=12?'inbound':'outbound';for(const v of ['outbound','inbound'])$(v).setAttribute('aria-pressed',String(v===direction));const today=taipei(now),tomorrow=taipei(new Date(+now+86400000));$('date').value=hour>=20&&data.days?.[tomorrow]?tomorrow:data.days?.[today]?today:tomorrow}render()}catch{$('freshness').textContent='資料讀取失敗。請稍後再試，或直接查看下方官方來源。'}finally{$('refresh').disabled=false}}
for(const id of ['outbound','inbound'])$(id).onclick=()=>{direction=id;for(const v of ['outbound','inbound'])$(v).setAttribute('aria-pressed',String(v===id));render()};$('date').onchange=()=>{$('date').dataset.chosen='true';render()};$('refresh').onclick=refresh;setInterval(()=>{$('clock').textContent=stamp(new Date().toISOString())},1000);setInterval(()=>{if(!document.hidden)refresh()},60000);refresh();
function setupCustomLookup(){const box=document.createElement('section');box.className='lookup';box.innerHTML='<p class="eyebrow">自訂查詢</p><h2>輸入地點或車次</h2><p class="muted">搜尋目前已擷取資料；找不到時可直接開啟台鐵官方查詢。</p><form id="lookup-form"><div class="lookup-grid"><label>出發地<input id="from" placeholder="例如 吉安"></label><label>到達地<input id="to" placeholder="例如 瑞穗"></label><label>車次<input id="train-no" inputmode="numeric" placeholder="例如 306"></label><label>日期<input id="lookup-date" type="date"></label></div><div class="lookup-actions"><button type="submit">搜尋已擷取資料</button><button type="button" id="official-train">開啟官方車次動態</button><a target="_blank" rel="noopener" href="https://www.railway.gov.tw/tra-tip-web/tip/tip001/tip112/gobytime">官方路線／時刻查詢 ↗</a></div></form><div id="lookup-results" class="lookup-results" role="status"></div>';document.querySelector('.journey').after(box);$('lookup-date').value=$('date').value;$('lookup-form').onsubmit=e=>{e.preventDefault();const date=$('lookup-date').value||$('date').value,from=$('from').value.trim(),to=$('to').value.trim(),no=$('train-no').value.trim(),all=Object.values(data?.days||{}).flatMap(d=>d.trains||[]),found=all.filter(t=>(!from||t.from.includes(from))&&(!to||t.to.includes(to))&&(!no||t.no===no)&&(!date||Object.values(data.days||{}).some(d=>d.trains?.includes(t))));$('lookup-results').innerHTML=found.length?found.map(t=>`<div class="result"><b>${esc(t.type)} ${esc(t.no)}</b>　${esc(t.from)} ${esc(t.departure)} → ${esc(t.to)} ${esc(t.arrival)}<br><span>${esc(t.status||'時刻已取得・即時狀態未提供')}</span></div>`).join(''):'<div class="empty">目前擷取資料沒有符合項目，請用官方路線查詢。</div>'};$('official-train').onclick=()=>{const no=$('train-no').value.trim(),date=($('lookup-date').value||$('date').value).replaceAll('-','/');if(no)window.open(`https://www.railway.gov.tw/tra-tip-web/tip/tip001/tip112/querybytrainno?rideDate=${date}&trainNo=${encodeURIComponent(no)}`,'_blank');else window.open('https://www.railway.gov.tw/tra-tip-web/tip/tip001/tip112/gobytime','_blank')};}
setupCustomLookup();
if($('lookup-form'))$('lookup-form').onsubmit=e=>{e.preventDefault();const date=$('lookup-date').value||$('date').value,from=$('from').value.trim(),to=$('to').value.trim(),no=$('train-no').value.trim(),all=Object.entries(data?.days||{}).flatMap(([day,d])=>(d.trains||[]).map(t=>({...t,day}))),found=all.filter(t=>t.day===date&&(!from||t.from.includes(from))&&(!to||t.to.includes(to))&&(!no||t.no===no));$('lookup-results').innerHTML=found.length?found.map(t=>`<div class="result"><b>${esc(t.type)} ${esc(t.no)}</b>　${esc(t.from)} ${esc(t.departure)} → ${esc(t.to)} ${esc(t.arrival)}<br><span>${esc(t.status||'時刻已取得・即時狀態未提供')}</span></div>`).join(''):'<div class="empty">目前擷取資料沒有符合項目，請用官方路線查詢。</div>'};
const timing=document.createElement('section');timing.className='timing';timing.innerHTML='<h2>資料怎麼更新？</h2><p><b>列車：</b>GitHub Actions 每天台灣時間 05:07–07:57、15:07–18:57 約每 10 分鐘啟動一次；21:13 會預抓隔日班次。每次工作依序讀取台鐵官方頁，頁與頁之間至少間隔 2 秒。</p><p><b>天氣：</b>吉安、瑞穗、花蓮各自讀取中央氣象署鄉鎮預報；同一地點至少間隔 1 小時才重抓。官方預報以逐 3 小時欄位提供，頁面會顯示實際取回時間。</p><p><b>時間差：</b>頁面上的「資料取回」是上一輪成功取得時間，不是現在時間；列車資料超過 15 分鐘、天氣超過 3 小時會標示過期。GitHub 排程可能延遲，按「更新畫面」只重新讀取已發布資料，不會臨時啟動爬蟲。</p>';document.querySelector('.lookup').after(timing);
const presets=document.createElement('div');presets.className='presets';presets.innerHTML='<span>常用路線</span><button type="button" data-from="吉安" data-to="瑞穗">吉安 → 瑞穗</button><button type="button" data-from="瑞穗" data-to="吉安">瑞穗 → 吉安</button><button type="button" data-from="瑞穗" data-to="花蓮">瑞穗 → 花蓮</button>';document.querySelector('#lookup-form').before(presets);$('from').value='吉安';$('to').value='瑞穗';for(const b of presets.querySelectorAll('button'))b.onclick=()=>{$('from').value=b.dataset.from;$('to').value=b.dataset.to;$('lookup-form').requestSubmit()};
